const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/prime_change_orders/%7Bprime_change_order_id%7D/line_items',
  headers: {'content-type': 'application/json'},
  body: {
    prime_line_item_id: '12345',
    rate_value_id: '01JFHMDB8AD4750F18KN8R2TF1',
    resource_id: '01JFHMDB8AD4750F18KN8R2TF2',
    amount: '1000.0',
    description: 'Cleanup',
    quantity: '20.0',
    unit_cost: '50.00',
    uom: 'Hours',
    wbs_code_id: '34567',
    tax_code_id: '12345',
    funding_rule_id: '12345'
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/prime_change_orders/%7Bprime_change_order_id%7D/line_items"),
    Content = new StringContent("{\"prime_line_item_id\":\"12345\",\"rate_value_id\":\"01JFHMDB8AD4750F18KN8R2TF1\",\"resource_id\":\"01JFHMDB8AD4750F18KN8R2TF2\",\"amount\":\"1000.0\",\"description\":\"Cleanup\",\"quantity\":\"20.0\",\"unit_cost\":\"50.00\",\"uom\":\"Hours\",\"wbs_code_id\":\"34567\",\"tax_code_id\":\"12345\",\"funding_rule_id\":\"12345\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

